Definition sm_ok (ps : SR.post_spec) (i : nat) (X : kentry) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20}^3!2+6!2+6+7+8+8$ps;R+^1$i;R+^2$X;R+K!2'^3!2'^3!4'^4'^5'M'N#1!:'^6!1,0|F2c4000;'^7!1'^8#30!4'^9'^:#2'^;!1,9!2+6+7+7!4'^9!1+51#2'^<!1,91!1,0,A}^80#1!3'^=+K!1'^>#1'W").
Definition callee (ps : SR.post_spec) (i j : nat) (c cj : CC.cutpoint) (scr : Z) (ng : nat) (BLk : CA.blocks) (wregs : list SGP.region) (news : list kentry) (a0x : option expr) (csp : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 12 "S60!1,9!2+6+7+7!4'^9'^:#;'^;0!2+6!2+6+7+8+8!1+52!1,92!4'^93#;'^<4$ps;R+^1$i;R+^2$j;R+^2$c;R+^?$cj;R+^?$scr;R+8$ng;R+^2$BLk;R'^:$wregs;R!1+5'C$news;R!1+5+K$a0x;R!1+^@+7$csp;R+8!2'^A!5'^B'^C'^7#915-^@RN$x;R!1+^@+^D+^E!C'^F'^C'^7'^5'M'N#7#6#55#4#3#2#9#<#815!4'^9'^:#:'^;0!4'^93#:'^<42$ci;R+^D!2'^G!1'^H#1#2,^I").
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      if Z.eqb pc RETPC then
        (CBA.exit_base_chk GT.NF RETPC c ps && CBA.regions_eqb (CC.cp_F c) CPFX && Nat.ltb 53 (CC.cp_nx c)
         && match CHA.retire_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS []) with Some fle => expr_eqb fle FLE | None => false end
         && has cells (KWord (SA FLE 0) 1 (ELit 0))
         && ((Nat.eqb i 5 && has cells (KWord (SA PE 211) 1 (ELit 0))) || (Nat.leb 6 i && Nat.leb i 7 && has cells (KWord (SA PE 211) 1 (ELit 1)))))%bool
      else
        match CH2.ret_of G.RETS i k with
        | Some j =>
            match nth_error G.CPS j with
            | Some cj =>
                (Z.eqb (SR.ps_pc ps) pc &&
                 if Z.eqb pc PC_SM then (Nat.eqb i 0 && Nat.eqb j 1 && CBA.regions_eqb (CC.cp_F c) CPF0
                                        && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                        && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 512 1 (nth i G.BLS []) (nth i FFS []) [] (List.filter (sm_ok ps i) (CC.cp_know cj)) None c ps cj
                                                   (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                           | Some ci => (Nat.eqb (CH2.ci_nx ci) 48 && Z.eqb (CH2.ci_csp ci) (-128))%bool | None => false end)
                 else if Z.eqb pc PC_DEC then (Nat.eqb i 1 && Nat.eqb j 2 && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 53 (CC.cp_nx c)
                                              && callee ps i j c cj 9120 0 [] DEC_W NEWS_D None (-128)
                                              && CL.ps_reg_is ps 10 A0E && CL.ps_reg_is ps 11 A1E && CL.ps_reg_is ps 12 VPE && has cells (KWord (SA FE 120) 8 FLE) && CC.has_cell (CC.cp_know c) KZF)
                 else if (Z.eqb pc PC_VINT || Z.eqb pc PC_VSTR) then      (* [comment removed for export] *)
                                             (Nat.eqb i 2 && Nat.leb 3 j && Nat.leb j 4 && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 53 (CC.cp_nx c)
                                              && CHA.frames_eqb (nth j FFS []) (nth i FFS [])
                                              && callee ps i j c cj XKA.VIS 0 (nth i G.BLS []) (if Z.eqb pc PC_VINT then WENCE else WENC) NEWS_F (Some (ELit 1)) (-128) && has cells (KWord (SA FE 120) 8 FLE)
                                              && CL.ps_reg_is ps 10 VE
                                              && (Z.eqb pc PC_VINT || (CL.ps_reg_is ps 11 SVA && CL.ps_reg_is ps 12 (ELit 3) && has cells (KWord (SA FE 64) 8 (EVar 32)) && has cells (KWord (SA FE 72) 8 (EVar 33))
                                                                      && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 8)) 1 (ELit 0)) && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 9)) 1 (ELit 0))))
                                              && has cells (KZero (SA (CHA.SRL3 VE) SBz) (ELit 51)) && has cells (KZero (SA (CHA.SRL3 S2E) SBz) (ELit 3)))
                 else if Z.eqb pc PC_SETEC then (Nat.eqb i 2 && Nat.eqb j 5 && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 53 (CC.cp_nx c)
                                              && callee ps i j c cj 1024 0 [] SETEC_W NEWS_F None (-128)
                                              && CL.ps_reg_is ps 10 EE && CL.ps_reg_is ps 11 (ELit 19) && has cells (KWord (SA FE 120) 8 FLE))
                 else if Z.eqb pc PC_AV then (Nat.leb 3 i && Nat.leb i 4 && Nat.eqb j (i + 3) && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 53 (CC.cp_nx c)
                                              && callee ps i j c cj 1152 0 [] AV_W NEWS_A None (-128)
                                              && CL.ps_reg_is ps 10 PE && CL.ps_reg_is ps 11 EE && has cells (KWord (SA PE 211) 1 (ELit 1)) && has cells (KWord (SA FE 120) 8 FLE))
                 else false)%bool
            | None => false end
        | None => false end
  end.
Lemma leaf_ok : CH2.leaves_all G.CPS G.TAGS leaf_chk = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,^J+^E,^K!3+^L+^E!3'^M'^N'^O'^P,^K").
Qed.
