Definition wdec_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TOther pc =>
      if Z.eqb pc PC_DEC then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 9120 0 [] (nth i FFS []) DEC_W NEWS_D None c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                 | Some ci => Nat.eqb (CH2.ci_nx ci) 65 | None => false end
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_SETEC then (Nat.ltb 70 (CC.cp_nx c) && negb (RLF.byte_adm 70 (SR.ps_cells ps) 0) && negb (RLF.byte_adm 70 (SR.ps_cells ps) 34))%bool
      else true
  | _ => true
  end.
Lemma wdec_ok : CH2.leaves_all G.CPS G.TAGS wdec_chk = true.
